CategoryTheory.CostructuredArrow.isoMk_hom_left.{v₁, v₂, u₁, u₂} {C : Type u₁} [Category.{v₁, u₁} C] {D : Type u₂}
  [Category.{v₂, u₂} D] {T : D} {S : C ⥤ D} {f f' : CostructuredArrow S T} (g : f.left ≅ f'.left)
  (w : S.map g.hom ≫ f'.hom = f.hom := by cat_disch) : (CostructuredArrow.isoMk g w).hom.left = g.hom
CategoryTheory.CostructuredArrow.isoMk_inv_left.{v₁, v₂, u₁, u₂} {C : Type u₁} [Category.{v₁, u₁} C] {D : Type u₂}
  [Category.{v₂, u₂} D] {T : D} {S : C ⥤ D} {f f' : CostructuredArrow S T} (g : f.left ≅ f'.left)
  (w : S.map g.hom ≫ f'.hom = f.hom := by cat_disch) : (CostructuredArrow.isoMk g w).inv.left = g.inv
CategoryTheory.Comma.isoMk_hom_left.{v₁, v₂, v₃, u₁, u₂, u₃} {A : Type u₁} [Category.{v₁, u₁} A] {B : Type u₂}
  [Category.{v₂, u₂} B] {T : Type u₃} [Category.{v₃, u₃} T] {L₁ : A ⥤ T} {R₁ : B ⥤ T} {X Y : Comma L₁ R₁}
  (l : X.left ≅ Y.left) (r : X.right ≅ Y.right) (h : L₁.map l.hom ≫ Y.hom = X.hom ≫ R₁.map r.hom := by cat_disch) :
  (Comma.isoMk l r h).hom.left = l.hom
CategoryTheory.Comma.isoMk_inv_left.{v₁, v₂, v₃, u₁, u₂, u₃} {A : Type u₁} [Category.{v₁, u₁} A] {B : Type u₂}
  [Category.{v₂, u₂} B] {T : Type u₃} [Category.{v₃, u₃} T] {L₁ : A ⥤ T} {R₁ : B ⥤ T} {X Y : Comma L₁ R₁}
  (l : X.left ≅ Y.left) (r : X.right ≅ Y.right) (h : L₁.map l.hom ≫ Y.hom = X.hom ≫ R₁.map r.hom := by cat_disch) :
  (Comma.isoMk l r h).inv.left = l.inv
CategoryTheory.Over.isoMk_hom_left.{v₁, u₁} {T : Type u₁} [Category.{v₁, u₁} T] {X : T} {f g : Over X}
  (hl : f.left ≅ g.left) (hw : hl.hom ≫ g.hom = f.hom := by cat_disch) : (Over.isoMk hl hw).hom.left = hl.hom
CategoryTheory.Over.isoMk_inv_left.{v₁, u₁} {T : Type u₁} [Category.{v₁, u₁} T] {X : T} {f g : Over X}
  (hl : f.left ≅ g.left) (hw : hl.hom ≫ g.hom = f.hom := by cat_disch) : (Over.isoMk hl hw).inv.left = hl.inv
CategoryTheory.eqToHom_map.{v₁, v₂, u₁, u₂} {C : Type u₁} [Category.{v₁, u₁} C] {D : Type u₂} [Category.{v₂, u₂} D]
  (F : C ⥤ D) {X Y : C} (p : X = Y) : F.map (eqToHom p) = eqToHom ⋯
CategoryTheory.eqToHom_trans.{v₁, u₁} {C : Type u₁} [Category.{v₁, u₁} C] {X Y Z : C} (p : X = Y) (q : Y = Z) :
  eqToHom p ≫ eqToHom q = eqToHom ⋯
CategoryTheory.eqToHom_refl.{v₁, u₁} {C : Type u₁} [CategoryStruct.{v₁, u₁} C] (X : C) (p : X = X) : eqToHom p = 𝟙 X
